return {
  json: {
    strategy_status: 'ready_for_production',
    campaign_meta: {
      campaign_brief: 'Create an Instagram-first creative package that can also support broader marketing execution.',
      product_name: 'Example product',
      target_audience: 'Women 18-30 interested in lifestyle and beauty content.',
      campaign_goal: 'Drive clicks and conversions while building a consistent visual identity.',
      platform: 'instagram',
      visual_mode: 'synthetic_original',
      identity_mode: 'original_brand_talent'
    },
    sales: {
      summary: 'Lead with a bundle offer and a direct click CTA.',
      primary_offer: 'Starter bundle with limited-time pricing',
      cta: 'Tap to shop',
      conversion_angle: 'Soft-luxury lifestyle framing with a clear offer.',
      proof_points: ['Customer testimonials available', 'Bundle saves compared to single-item purchase'],
      risks: ['Price sensitivity', 'Trust barrier for first-time buyers'],
      recommended_actions: ['Use social proof in captions', 'Keep CTA visible in every asset']
    },
    marketing: {
      summary: 'Instagram-first lifestyle hooks with reusable caption angles.',
      target_segments: ['Lifestyle shoppers', 'Beauty-adjacent audience', 'Aspirational casual content audience'],
      hooks: ['Soft routine energy', 'What I actually reach for', 'Everyday luxury without trying too hard'],
      caption_angles: ['Routine angle', 'Favorite-find angle', 'Lifestyle diary angle', 'Low-effort glam angle', 'Beach day angle', 'Car selfie angle'],
      hashtag_clusters: ['#lifestylecreator #softluxury #beautyfinds', '#everydaystyle #routinecontent #itgirlenergy'],
      channel_notes: ['Use 4:5 crops for feed', 'Keep the first line of the caption punchy'],
      recommended_actions: ['Prioritize save-worthy captions', 'Test short hooks on static assets']
    },
    product: {
      summary: 'Use soft natural light, polished but casual styling, and clean backgrounds.',
      visual_style: 'soft luxury lifestyle with natural light',
      scene_concepts: ['car selfie', 'beach portrait', 'clean indoor mirror shot', 'cafe close-up', 'sunlit casual portrait', 'travel lifestyle frame'],
      prompt_components: ['soft natural light', 'polished casual styling', 'clean skin texture', 'neutral palette', 'high-end but candid feel'],
      negative_prompt: 'distorted hands, extra fingers, warped background, text artifacts, oversmoothed skin, duplicate body parts',
      image_prompt_templates: ['car interior portrait with soft natural light and polished casual styling', 'beach portrait with clean composition and neutral palette', 'sunlit indoor lifestyle portrait with soft luxury tone', 'mirror selfie aesthetic with minimal clean background', 'cafe lifestyle close-up with polished natural makeup', 'travel-style portrait with warm daylight and editorial framing'],
      recommended_actions: ['Keep prompts stylistically consistent', 'Avoid overloading scenes with props']
    },
    creative_targets: {
      asset_count: 6,
      platform: 'instagram'
    },
    next_step: 'Pass this item into the Creative Production sub-workflow.'
  }
};

const payload = $json;
if (!payload.sales || !payload.marketing || !payload.product) {
  throw new Error('Incoming strategy package is missing sales, marketing, or product branches.');
}
const creativeTargets = payload.creative_targets ?? {
  asset_count: Math.max(payload.product.image_prompt_templates?.length ?? 0, payload.marketing.caption_angles?.length ?? 0, 6),
  platform: payload.campaign_meta?.platform ?? 'instagram'
};
return {
  json: {
    strategy_status: payload.strategy_status ?? 'ready_for_production',
    campaign_meta: payload.campaign_meta ?? {},
    sales: payload.sales,
    marketing: payload.marketing,
    product: payload.product,
    creative_targets: creativeTargets
  }
};

const payload = $json;
const assetCount = Math.max(payload.creative_targets?.asset_count ?? 0, 1);
const promptTemplates = payload.product.image_prompt_templates ?? [];
const hooks = payload.marketing.hooks ?? [];
const captionAngles = payload.marketing.caption_angles ?? [];
const assets = Array.from({ length: assetCount }, (_, index) => ({
  asset_index: index + 1,
  hook: hooks[index % Math.max(hooks.length, 1)] ?? '',
  caption_angle: captionAngles[index % Math.max(captionAngles.length, 1)] ?? '',
  prompt_template: promptTemplates[index % Math.max(promptTemplates.length, 1)] ?? '',
  offer: payload.sales.primary_offer,
  cta: payload.sales.cta
}));
return {
  json: {
    ...payload,
    creative_pack: {
      asset_count: assetCount,
      render_defaults: {
        aspect_ratio: '4:5',
        batch_size: 1,
        safety_mode: 'strict'
      },
      assets
    }
  }
};

const payload = $json;
const promptComponents = payload.product.prompt_components ?? [];
const negativePrompt = payload.product.negative_prompt ?? '';
const image_model_requests = (payload.creative_pack?.assets ?? []).map((asset) => ({
  asset_index: asset.asset_index,
  prompt: [asset.prompt_template, ...promptComponents].filter(Boolean).join(', '),
  negative_prompt: negativePrompt,
  aspect_ratio: payload.creative_pack.render_defaults.aspect_ratio,
  batch_size: payload.creative_pack.render_defaults.batch_size,
  safety_mode: payload.creative_pack.render_defaults.safety_mode,
  metadata: {
    hook: asset.hook,
    caption_angle: asset.caption_angle,
    offer: asset.offer,
    cta: asset.cta
  }
}));
return {
  json: {
    campaign_meta: payload.campaign_meta,
    creative_pack: payload.creative_pack,
    image_model_requests
  }
};

const payload = $json;
const hashtagClusters = payload.marketing.hashtag_clusters ?? [];
const caption_assets = (payload.creative_pack?.assets ?? []).map((asset, index) => ({
  asset_index: asset.asset_index,
  caption: [asset.hook, asset.caption_angle, payload.sales.cta].filter(Boolean).join(' | '),
  hashtag_cluster: hashtagClusters[index % Math.max(hashtagClusters.length, 1)] ?? ''
}));
return {
  json: {
    campaign_meta: payload.campaign_meta,
    creative_pack: payload.creative_pack,
    caption_assets
  }
};

const items = $input.all();
let imageData = null;
let captionData = null;
for (const item of items) {
  if (item.json.image_model_requests) imageData = item.json;
  if (item.json.caption_assets) captionData = item.json;
}
if (!imageData || !captionData) {
  throw new Error('Missing image model requests or caption assets after merge.');
}
const textBlob = JSON.stringify({ image_model_requests: imageData.image_model_requests, caption_assets: captionData.caption_assets }).toLowerCase();
const blockedTerms = ['exact likeness', 'same as this real person', 'copy this influencer', 'celebrity clone'];
for (const term of blockedTerms) {
  if (textBlob.includes(term)) {
    throw new Error('Compliance gate blocked a mimic or impersonation signal: ' + term);
  }
}
return [{
  json: {
    campaign_meta: imageData.campaign_meta,
    creative_pack: imageData.creative_pack,
    image_model_requests: imageData.image_model_requests,
    caption_assets: captionData.caption_assets,
    compliance_status: 'passed',
    review_required: true
  }
}];

return {
  json: {
    ...$json,
    approval_status: 'pending_manual_review',
    approval_notes: 'Replace this node with Slack, email, Airtable, or a form-based approval step.'
  }
};

return {
  json: {
    ...$json,
    render_queue_payload: {
      provider: 'replace_with_image_provider',
      assets: $json.image_model_requests,
      note: 'Replace this placeholder with HTTP Request, queue, or custom renderer integration.'
    }
  }
};

return {
  json: {
    status: 'production_package_ready',
    campaign_meta: $json.campaign_meta,
    creative_pack: $json.creative_pack,
    image_model_requests: $json.image_model_requests,
    caption_assets: $json.caption_assets,
    render_queue_payload: $json.render_queue_payload,
    compliance_status: $json.compliance_status,
    approval_status: $json.approval_status,
    next_actions: [
      'Replace Prepare Render Queue Payload with your image provider or renderer.',
      'Replace Human Approval Placeholder with your real approval process.',
      'Add storage or Meta Graph API publishing after approval.'
    ]
  }
};
